esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to call migrateTo as this contract (which is NOT the original creator of C
    // when the checker deploys a fresh C) and assert the general rule about effects.
    function run(address to) public payable {
        require(to != address(0), "nonzero target");

        // read before-balance
        uint256 beforeBal = address(c).balance;

        // try to migrate; capture revert status
        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;

        // General rule: if migrateTo succeeded then contract balance is zero afterwards;
        // if it reverted then balance is unchanged.
        assert(
            reverted ? (afterBal == beforeBal) : (afterBal == 0)
        );
    }

    receive() external payable {}
}

